&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;div style=&quot;float: right; padding: 0 0 8px 8px&quot;&gt;&lt;table id=&quot;TocContainerTable&quot;&gt;&lt;tr&gt;&lt;td&gt;&lt;div id=&quot;TocContainer&quot;&gt;&lt;p class=&quot;small&quot;&gt;&lt;b&gt;Table of Contents&lt;/b&gt;&lt;span id=&quot;ExpandTocSpan&quot;&gt; [&lt;a href=&quot;#&quot; onclick=&quot;javascript:if(document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]==&#39;none&#39;) document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;&#39;; else document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;none&#39;; return false;&quot;&gt;Hide/Show&lt;/a&gt;]&lt;/span&gt;&lt;/p&gt;&lt;div id=&quot;Toc&quot;&gt;&lt;p&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Type_de_pi&#232;ge_0&quot;&gt; Type de pi&#232;ge &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Facteur_de_puissance_d’un_pi&#232;ge_1&quot;&gt; Facteur de puissance d’un pi&#232;ge &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Co&#251;t_d’un_pi&#232;ge_m&#233;canique_2&quot;&gt;Co&#251;t d’un pi&#232;ge m&#233;canique&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Co&#251;t_d’un_pi&#232;ge_magique_&#224;_objet_3&quot;&gt;Co&#251;t d’un pi&#232;ge magique &#224; objet&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Co&#251;t_d’un_pi&#232;ge_&#224;_sort_4&quot;&gt; Co&#251;t d’un pi&#232;ge &#224; sort &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#DD_du_test_d’Artisanat_des_pi&#232;ges_m&#233;caniques_5&quot;&gt; DD du test d’Artisanat des pi&#232;ges m&#233;caniques&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;i&gt;Voir aussi la &lt;a class=&quot;pagelink&quot; href=&quot;Pi&#232;ges.html&quot; title=&quot;Les pi&#232;ges&quot;&gt;description des pi&#232;ges&lt;/a&gt; et des &lt;a class=&quot;pagelink&quot; href=&quot;Exemples-De-Pi&#232;ges.html&quot; title=&quot;Exemples de pi&#232;ges&quot;&gt;exemples de pi&#232;ges&lt;/a&gt;.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TYPE&quot; href=&quot;#TYPE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt; Type de pi&#232;ge &lt;a class=&quot;headeranchor&quot; id=&quot;Type_de_pi&#232;ge_0&quot; href=&quot;#Type_de_pi&#232;ge_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;C’est un proc&#233;d&#233; assez simple. Il faut tout d’abord d&#233;cider du type de pi&#232;ge que vous souhaitez cr&#233;er.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Pi&#232;ges m&#233;caniques.&lt;/b&gt; Choisissez les &#233;l&#233;ments que vous souhaitez associer au pi&#232;ge et ajoutez les modifications ad&#233;quates au facteur de puissance (voir la table ci-dessous) pour obtenir le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres.html#FP&quot; title=&quot;Les rencontres&quot;&gt;FP&lt;/a&gt; final du pi&#232;ge afin d’en d&#233;duire le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du test d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (fabrication des pi&#232;ges) que le personnage doit effectuer (voir Tableau &quot;DD du test d’Artisanat des pi&#232;ges&quot; plus bas).&lt;br /&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;table CLASS=&quot;tablo centre&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MODIFFPMECA&quot; href=&quot;#MODIFFPMECA&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Modificateurs au FP des pi&#232;ges m&#233;caniques&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;&#201;l&#233;ment&lt;/td&gt;&lt;td&gt;Modificateur au FP&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td COLSPAN=&quot;2&quot;&gt;&lt;b&gt;DD du test de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;&lt;/b&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt; 15 ou moins&lt;/td&gt;&lt;td&gt;-1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;16-20&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;21-25&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;26–29&lt;/td&gt;&lt;td&gt;+2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;30 ou plus&lt;/td&gt;&lt;td&gt;+3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td COLSPAN=&quot;2&quot;&gt;&lt;b&gt;DD du test de &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt;&lt;/b&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;15 ou moins&lt;/td&gt;&lt;td&gt;–1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;16-20&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;21-25&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;26–29&lt;/td&gt;&lt;td&gt;+2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;30 ou plus&lt;/td&gt;&lt;td&gt;+3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td COLSPAN=&quot;2&quot;&gt;&lt;b&gt;DD du jet de R&#233;flexes (fosses et autres pi&#232;ges autorisant un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;JdS&lt;/a&gt;)&lt;/b&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt; 15 ou moins&lt;/td&gt;&lt;td&gt;–1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;16-20&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;21-25&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;26–29&lt;/td&gt;&lt;td&gt;+2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;30 ou plus&lt;/td&gt;&lt;td&gt;+3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td COLSPAN=&quot;2&quot;&gt;&lt;b&gt;Bonus &#224; l’attaque (corps &#224; corps ou &#224; distance)&lt;/b&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;+0 ou moins&lt;/td&gt;&lt;td&gt;–2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;+1 &#224; +5&lt;/td&gt;&lt;td&gt;–1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;+6 &#224; +10&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;+11 &#224; +15&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;+16 &#224; +20&lt;/td&gt;&lt;td&gt;+2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Attaque de contact&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td COLSPAN=&quot;2&quot;&gt;&lt;b&gt;D&#233;g&#226;ts/effet&lt;/b&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;D&#233;g&#226;ts moyens&lt;/td&gt;&lt;td&gt;+1/10 points&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td COLSPAN=&quot;2&quot;&gt;&lt;b&gt;&#201;l&#233;ments divers&lt;/b&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Cibles multiples&lt;/td&gt;&lt;td&gt;+1 (pas de dommage)&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Liquide&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Ne rate jamais&lt;/td&gt;&lt;td&gt;+2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Objet sp&#233;cial&lt;/td&gt;&lt;td&gt;niveau du sort imit&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Proximit&#233; ou visuel&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Remise en place automatique&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/td&gt;&lt;td&gt;
&lt;table CLASS=&quot;tablo centre&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;Modificateur de FP selon le poison employ&#233;&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Poison&lt;/td&gt;&lt;td&gt;FP du poison &lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Ajonc &#224; feuilles bleues&lt;/td&gt;&lt;td&gt;+1 &lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Bile de dragon&lt;/td&gt;&lt;td&gt;+6 &lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Brume de folie&lt;/td&gt;&lt;td&gt;+4 &lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Cendres d’ungol&lt;/td&gt;&lt;td&gt;+3 &lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Essence d’ombre&lt;/td&gt;&lt;td&gt;+3 &lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Extrait de lotus noir&lt;/td&gt;&lt;td&gt;+8 &lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Extrait de sanvert&lt;/td&gt;&lt;td&gt;+1 &lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Mortelame&lt;/td&gt;&lt;td&gt;+5 &lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Nitharite&lt;/td&gt;&lt;td&gt;+4 &lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;P&#226;te de malyss&lt;/td&gt;&lt;td&gt;+3 &lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Poudre d’assonne&lt;/td&gt;&lt;td&gt;+3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Terrinave&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Vapeurs d’othur br&#251;l&#233;&lt;/td&gt;&lt;td&gt;+6&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Venin d’araign&#233;e de taille M&lt;/td&gt;&lt;td&gt;+2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Venin de gu&#234;pe g&#233;ante&lt;/td&gt;&lt;td&gt;+3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Venin de mille-pattes de taille P&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Venin de scorpion de taille G&lt;/td&gt;&lt;td&gt;+3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Venin de ver pourpre&lt;/td&gt;&lt;td&gt;+4&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Venin de vip&#232;re &#224; t&#234;te noire&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Venin de wiverne&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;note&quot;&gt;&lt;td COLPAN=&quot;2&quot;&gt;&lt;i&gt;Voir la section sur les &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;Les poisons  &quot;&gt;poisons&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;b&gt;Pi&#232;ges magiques.&lt;/b&gt; L&#224; encore, choisissez les &#233;l&#233;ments qui vous conviennent et d&#233;terminez le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres.html#FP&quot; title=&quot;Les rencontres&quot;&gt;FP&lt;/a&gt; du pi&#232;ge en fonction (voir la table ci-dessous). Si un PJ souhaite concevoir et construire un pi&#232;ge magique, il doit disposer du don &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Dobjets-Merveilleux.html&quot; title=&quot;Cr&#233;ation d&amp;#39;objets merveilleux&quot;&gt;Cr&#233;ation d’objets merveilleux&lt;/a&gt;. De plus, il doit &#234;tre capable de lancer le ou les sorts n&#233;cessaire &#224; la conception du pi&#232;ge, sans quoi il devra louer les services d’un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; qui s’en chargera pour lui.&lt;br /&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre autoalt&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MODIFFPMAGIQUES&quot; href=&quot;#MODIFFPMAGIQUES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Modificateurs au FP des pi&#232;ges magiques&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;&#201;l&#233;ment&lt;/td&gt;&lt;td&gt;Modificateur au FP&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Sort du plus haut niveau&lt;/td&gt;&lt;td&gt;+ niveau du sort&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Sort provoquant des d&#233;g&#226;ts&lt;/td&gt;&lt;td&gt;+1/10 points de d&#233;g&#226;ts moyens&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt; Facteur de puissance d’un pi&#232;ge &lt;a class=&quot;headeranchor&quot; id=&quot;Facteur_de_puissance_d’un_pi&#232;ge_1&quot; href=&quot;#Facteur_de_puissance_d’un_pi&#232;ge_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Pour calculer le facteur de puissance d’un pi&#232;ge, ajoutez tous les modificateurs de &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres.html#FP&quot; title=&quot;Les rencontres&quot;&gt;FP&lt;/a&gt; (voir les deux tables de la section pr&#233;c&#233;dente) au &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres.html#FP&quot; title=&quot;Les rencontres&quot;&gt;FP&lt;/a&gt; de base du pi&#232;ge.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Pi&#232;ge m&#233;canique.&lt;/b&gt; Le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres.html#FP&quot; title=&quot;Les rencontres&quot;&gt;FP&lt;/a&gt; de base d’un pi&#232;ge m&#233;canique est &#233;gal &#224; 0. Si son &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres.html#FP&quot; title=&quot;Les rencontres&quot;&gt;FP&lt;/a&gt; final est toujours &#233;gal &#224; 0, ajoutez-lui des &#233;l&#233;ments jusqu’&#224; ce que le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres.html#FP&quot; title=&quot;Les rencontres&quot;&gt;FP&lt;/a&gt; s’&#233;l&#232;ve &#224; 1 au moins.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Pi&#232;ge magique.&lt;/b&gt; Pour un pi&#232;ge &#224; sort ou &#224; objet magique, le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres.html#FP&quot; title=&quot;Les rencontres&quot;&gt;FP&lt;/a&gt; de base est &#233;gal &#224; 1. C’est le sort du plus haut niveau qui modifie le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres.html#FP&quot; title=&quot;Les rencontres&quot;&gt;FP&lt;/a&gt; (voir la table &lt;a class=&quot;pagelink&quot; href=&quot;Conception-De-Pi&#232;ges.html#MODIFFPMAGIQUES&quot; title=&quot;Conception d&amp;#39;un pi&#232;ge&quot;&gt;Modificateurs au FP des pi&#232;ges magiques&lt;/a&gt;).&lt;br /&gt;&lt;br /&gt;&lt;b&gt;D&#233;g&#226;ts moyens.&lt;/b&gt; Si le pi&#232;ge m&#233;canique ou magique inflige des points de d&#233;g&#226;ts, calculez les d&#233;g&#226;ts moyens et arrondissez cette valeur au multiple de 10 le plus proche. Si le pi&#232;ge est con&#231;u pour atteindre des cibles multiples, multipliez cette valeur par 2. S’il est con&#231;u pour infliger des d&#233;g&#226;ts pendant une certaine dur&#233;e, multipliez cette valeur par le nombre de rounds pendant lequel le pi&#232;ge sera actif (ou le nombre moyen si la dur&#233;e est variable). Utilisez cette valeur pour ajuster le facteur de puissance du pi&#232;ge, comme le montre la &lt;a class=&quot;pagelink&quot; href=&quot;Conception-De-Pi&#232;ges.html#MODIFFPMECA&quot; title=&quot;Conception d&amp;#39;un pi&#232;ge&quot;&gt;table des modificateurs au FP des pi&#232;ges m&#233;caniques&lt;/a&gt;. Les d&#233;g&#226;ts dus au poison ne comptent pas, &#224; l’inverse de ceux qui d&#233;coulent des pieux ou d’attaques multiples.&lt;br /&gt;&lt;br /&gt;Pour ce qui est des pi&#232;ges magiques, on applique un seul modificateur au &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres.html#FP&quot; title=&quot;Les rencontres&quot;&gt;FP&lt;/a&gt;  : le niveau du sort du plus haut niveau utilis&#233; lors de la conception, ou les d&#233;g&#226;ts moyens (choisir le plus &#233;lev&#233;).&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Pi&#232;ges multiples.&lt;/b&gt; Si le pi&#232;ge est en fait constitu&#233; de plusieurs pi&#232;ges qui affectent la m&#234;me zone &#224; peu de choses pr&#232;s, d&#233;terminez le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres.html#FP&quot; title=&quot;Les rencontres&quot;&gt;FP&lt;/a&gt; de chacun s&#233;par&#233;ment.
&lt;ul&gt;&lt;li&gt;&lt;i&gt;Pi&#232;ges multiples interd&#233;pendants.&lt;/i&gt; Si un pi&#232;ge d&#233;pend du bon fonctionnement d’un autre, (c’est-&#224;-dire qu’on peut &#233;viter le second en n’&#233;tant pas victime du premier), les personnages gagnent un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Pointsdexperience.html&quot; title=&quot;PX&quot;&gt;PX&lt;/a&gt; &#233;gal &#224; la valeur totale des pi&#232;ges s’ils &#233;chappent au premier et ne d&#233;clenchent pas le second.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Pi&#232;ges multiples ind&#233;pendants.&lt;/i&gt; Si plusieurs pi&#232;ges agissent ind&#233;pendamment (si le fonctionnement de l’un n’affecte pas celui de l’autre), les personnages gagnent un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Pointsdexperience.html&quot; title=&quot;PX&quot;&gt;PX&lt;/a&gt; &#233;gal &#224; la valeur de celui auquel ils ont r&#233;ussi &#224; &#233;chapper.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Co&#251;t d’un pi&#232;ge m&#233;canique&lt;a class=&quot;headeranchor&quot; id=&quot;Co&#251;t_d’un_pi&#232;ge_m&#233;canique_2&quot; href=&quot;#Co&#251;t_d’un_pi&#232;ge_m&#233;canique_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Le co&#251;t de base d’un pi&#232;ge m&#233;canique est de 1 000 po x le facteur de puissance du pi&#232;ge. Si le d&#233;clencheur comporte des sorts, ajoutez ces co&#251;ts s&#233;par&#233;ment. Pour une remise en place automatique, augmentez le co&#251;t de 50%. Des pi&#232;ges tr&#232;s simples, comme les fosses, peuvent se r&#233;v&#233;ler tr&#232;s peu on&#233;reux, &#224; la discr&#233;tion du MJ, et leur fabrication peut avoisiner &#224; peine 250 po x facteur de puissance.&lt;br /&gt;&lt;br /&gt;Une fois ceci fait, ajoutez la valeur des objets sp&#233;ciaux et poisons incorpor&#233;s au pi&#232;ge. Si le pi&#232;ge b&#233;n&#233;ficie de l’un de ces &#233;l&#233;ments et si sa remise en place est automatique, multipliez le co&#251;t du poison ou de l’objet sp&#233;cial par 20 pour ce qui est des doses n&#233;cessaires.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Pi&#232;ges multiples.&lt;/b&gt; Si le pi&#232;ge est constitu&#233; de plusieurs pi&#232;ges reli&#233;s entre eux, d&#233;terminez le co&#251;t final de chacun s&#233;par&#233;ment, puis faites la somme des valeurs obtenues. Cela vaut pour les pi&#232;ges ind&#233;pendants et interd&#233;pendants (voir ci-dessus).&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Co&#251;t d’un pi&#232;ge magique &#224; objet&lt;a class=&quot;headeranchor&quot; id=&quot;Co&#251;t_d’un_pi&#232;ge_magique_&#224;_objet_3&quot; href=&quot;#Co&#251;t_d’un_pi&#232;ge_magique_&#224;_objet_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Pour cr&#233;er un pi&#232;ge magique &#224; objet, il faut d&#233;penser des pi&#232;ces d’or et louer les services d’un lanceur de sorts. La table ci-dessous r&#233;pertorie toutes ces d&#233;penses. Si le pi&#232;ge n&#233;cessite plusieurs sorts (par exemple, un d&#233;clencheur visuel ou sonore en plus de l’effet magique principal), le concepteur doit les payer tous (&#224; l’exception du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alarme.html&quot; title=&quot;Alarme&quot;&gt;alarme&lt;/a&gt;&lt;/i&gt;, gratuit &#224; moins qu’il soit lanc&#233; par un PNJ).&lt;br /&gt;&lt;br /&gt;Les prix donn&#233;s dans la table ci-dessous partent du principe que la personne qui fabrique le pi&#232;ge se charge de lancer les sorts n&#233;cessaires (ou qu’un autre PJ le fait gracieusement). Si elle doit louer les services d’un PNJ lanceur de sorts, le salaire de ce dernier s’ajoute au prix total (voir le Chapitre 6 &#224; ce sujet).&lt;br /&gt;&lt;br /&gt;Le temps de cr&#233;ation d’un pi&#232;ge &#224; objet magique est &#233;gal &#224; 1 jour par tranche de 500 po de son co&#251;t.&lt;br /&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre&quot;&gt;&lt;caption&gt;Modificateurs au co&#251;t des pi&#232;ges magiques&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;&#201;l&#233;ment&lt;/td&gt;&lt;td&gt;Modificateur au co&#251;t&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&amp;emsp;Sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alarme.html&quot; title=&quot;Alarme&quot;&gt;alarme&lt;/a&gt;&lt;/i&gt; en guise de d&#233;clencheur&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td COLSPAN=&quot;2&quot;&gt;&lt;b&gt;Pi&#232;ge &#224; usage unique&lt;/b&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;Chaque sort utilis&#233; dans le pi&#232;ge&lt;/td&gt;&lt;td&gt;+50 po &#215; niveau de lanceur de sorts &#215; niveau du sort&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&amp;emsp;Composantes mat&#233;rielles&lt;/td&gt;&lt;td&gt; +co&#251;t des composantes mat&#233;rielles&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td COLSPAN=&quot;2&quot;&gt;&lt;b&gt;Pi&#232;ge &#224; remise en place automatique&lt;/b&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;Chaque sort utilis&#233; dans le pi&#232;ge&lt;/td&gt;&lt;td&gt;+500 po &#215; niveau de lanceur de sorts &#215; niveau du sort&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&amp;emsp;Composantes mat&#233;rielles&lt;/td&gt;&lt;td&gt;+co&#251;t des composantes mat&#233;rielles&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt; Co&#251;t d’un pi&#232;ge &#224; sort &lt;a class=&quot;headeranchor&quot; id=&quot;Co&#251;t_d’un_pi&#232;ge_&#224;_sort_4&quot; href=&quot;#Co&#251;t_d’un_pi&#232;ge_&#224;_sort_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Un pi&#232;ge &#224; sort ne co&#251;te rien &#224; moins qu’il ne faille louer les services d’un PNJ lanceur de sorts.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt; DD du test d’Artisanat des pi&#232;ges m&#233;caniques&lt;a class=&quot;headeranchor&quot; id=&quot;DD_du_test_d’Artisanat_des_pi&#232;ges_m&#233;caniques_5&quot; href=&quot;#DD_du_test_d’Artisanat_des_pi&#232;ges_m&#233;caniques_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Une fois que vous avez calcul&#233; le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres.html#FP&quot; title=&quot;Les rencontres&quot;&gt;facteur de puissance&lt;/a&gt; du pi&#232;ge qu’un PJ souhaite concevoir et construire, d&#233;terminez le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du test d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (fabrication de pi&#232;ges) en vous reportant &#224; la table ci-contre.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Effectuer les tests.&lt;/b&gt; Pour d&#233;terminer l’avancement journalier de la construction d’un pi&#232;ge, le personnage effectue un test d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (fabrication de pi&#232;ges). Pour de plus amples informations sur ce type de test, reportez-vous &#224; la description de la comp&#233;tence &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre&quot;&gt;&lt;caption&gt;DD du test d’Artisanat des pi&#232;ges&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;FP du pi&#232;ge&lt;/td&gt;&lt;td&gt;DD de base du &lt;br/&gt;test d’Artisanat (fabrication de pi&#232;ges)&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;1–5&lt;/td&gt;&lt;td&gt;20&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;6–10&lt;/td&gt;&lt;td&gt;25&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;11–15&lt;/td&gt;&lt;td&gt;30&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;16+&lt;/td&gt;&lt;td&gt;35&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;&#201;l&#233;ments suppl&#233;mentaires&lt;/td&gt;&lt;td&gt;Modificateur au test&lt;br/&gt;d&#39;Artisanat (fabrication de pi&#232;ges)&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;D&#233;clencheur de proximit&#233;&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Remise en place automatique&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
